//! The approval channel's config (specs/004 research.md R3): ntfy with
//! `deny-all`, the gateway allowed only to publish to the person's topic
//! and the person only to read it. The users' bcrypt hashes go in a
//! generated `server.yml` (a `$` in an env file would be interpolated).

use anyhow::Result;
use std::path::Path;

pub const FILE: &str = "ntfy-server.yml";
pub const GATEWAY_USER: &str = "sesh-gateway";
pub const PERSON_USER: &str = "person";

pub fn server_yml(topic: &str, gateway_hash: &str, person_hash: &str) -> String {
    format!(
        "# Generated by `sesh up` (specs/004). Do not edit.\n\
listen-http: \":80\"\n\
base-url: \"http://127.0.0.1:8090\"\n\
auth-file: \"/var/lib/ntfy/auth.db\"\n\
auth-default-access: \"deny-all\"\n\
enable-login: true\n\
auth-users:\n  - \"{GATEWAY_USER}:{gateway_hash}:user\"\n  - \"{PERSON_USER}:{person_hash}:user\"\n\
auth-access:\n  - \"{GATEWAY_USER}:{topic}:wo\"\n  - \"{PERSON_USER}:{topic}:ro\"\n"
    )
}

fn hash_in(text: &str, user: &str) -> Option<String> {
    let prefix = format!("  - \"{user}:");
    text.lines()
        .find_map(|l| l.strip_prefix(&prefix))
        .and_then(|rest| rest.strip_suffix(":user\""))
        .map(str::to_string)
}

/// Writes `compose/ntfy-server.yml` unless the current one already matches
/// the topic and passwords. Returns whether it changed.
pub fn write_config(cdir: &Path, topic: &str, gateway_pw: &str, person_pw: &str) -> Result<bool> {
    let path = cdir.join(FILE);
    if let Ok(text) = std::fs::read_to_string(&path) {
        let ok = |user: &str, pw: &str| {
            hash_in(&text, user).is_some_and(|h| bcrypt::verify(pw, &h).unwrap_or(false))
        };
        if text.contains(&format!("\"{GATEWAY_USER}:{topic}:wo\""))
            && ok(GATEWAY_USER, gateway_pw)
            && ok(PERSON_USER, person_pw)
        {
            return Ok(false);
        }
    }
    let g = bcrypt::hash(gateway_pw, 10)?;
    let p = bcrypt::hash(person_pw, 10)?;
    std::fs::write(&path, server_yml(topic, &g, &p))?;
    Ok(true)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn writes_once_and_keeps_only_hashes() {
        let dir = std::env::temp_dir().join(format!("sesh-ntfy-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        assert!(write_config(&dir, "t1", "gw-pass-123", "person-pass-123").unwrap());
        let text = std::fs::read_to_string(dir.join(FILE)).unwrap();
        assert!(!text.contains("gw-pass-123") && !text.contains("person-pass-123"));
        assert!(text.contains("auth-default-access: \"deny-all\""));
        assert!(text.contains("\"sesh-gateway:t1:wo\"") && text.contains("\"person:t1:ro\""));
        assert!(
            !write_config(&dir, "t1", "gw-pass-123", "person-pass-123").unwrap(),
            "unchanged"
        );
        assert!(
            write_config(&dir, "t2", "gw-pass-123", "person-pass-123").unwrap(),
            "new topic"
        );
        assert!(
            write_config(&dir, "t2", "other", "person-pass-123").unwrap(),
            "new password"
        );
    }
}
